import{_ as e,o as t,c as o,a2 as r}from"./chunks/framework.C0KMm31j.js";const i="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_05_01_two_controls.png",s="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_05_02_profiles.png",c="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_05_03_network.png",n="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_05_04_injection.png",l="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_05_05_secrets.png",p="/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_05_06_approval.png",q=JSON.parse('{"title":"给 AI 权限之前先看懂：Codex 沙箱、审批与安全边界","description":"Codex 能读文件、运行命令和调用外部工具，因此安全不能只依赖一句“不要做危险操作”。OpenAI Docs 当前把本地控制拆成 Sandbox 与 Approval：前者决定技术上能接触什么，后者决定何时必须暂停并由人或自动审查器判断。","frontmatter":{"title":"给 AI 权限之前先看懂：Codex 沙箱、审批与安全边界","description":"Codex 能读文件、运行命令和调用外部工具，因此安全不能只依赖一句“不要做危险操作”。OpenAI Docs 当前把本地控制拆成 Sandbox 与 Approval：前者决定技术上能接触什么，后者决定何时必须暂停并由人或自动审查器判断。","date":"2026-08-10","topic":"AI 底层学习","section":"OpenAI官方文档解读","readingTime":5,"source":"2026-08-10/ai_codex_official_05_security_permissions.md","status":"archived","cover":"/article-assets/2026-08-10/ai_codex_official_05_01_two_controls.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"给 AI 权限之前先看懂：Codex 沙箱、审批与安全边界"}],["meta",{"property":"og:description","content":"Codex 能读文件、运行命令和调用外部工具，因此安全不能只依赖一句“不要做危险操作”。OpenAI Docs 当前把本地控制拆成 Sandbox 与 Approval：前者决定技术上能接触什么，后者决定何时必须暂停并由人或自动审查器判断。"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/ai/openai-codex-complete-guide"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_05_01_two_controls.png"}],["meta",{"property":"article:published_time","content":"2026-08-10"}],["meta",{"name":"twitter:title","content":"给 AI 权限之前先看懂：Codex 沙箱、审批与安全边界"}],["meta",{"name":"twitter:description","content":"Codex 能读文件、运行命令和调用外部工具，因此安全不能只依赖一句“不要做危险操作”。OpenAI Docs 当前把本地控制拆成 Sandbox 与 Approval：前者决定技术上能接触什么，后者决定何时必须暂停并由人或自动审查器判断。"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-10/ai_codex_official_05_01_two_controls.png"}],["meta",{"name":"robots","content":"noindex,follow"}]],"search":false,"prev":false,"next":false},"headers":[],"relativePath":"archive/ai-codex-official-05-security-permissions.md","filePath":"archive/ai-codex-official-05-security-permissions.md","lastUpdated":null}'),d={name:"archive/ai-codex-official-05-security-permissions.md"};function h(_,a,m,f,u,b){return t(),o("div",null,[...a[0]||(a[0]=[r('<blockquote><p>本文为历史归档版本，不再更新。请阅读<a href="/Nav2ArticlesSite/ai/openai-codex-complete-guide">当前版本</a>。</p></blockquote><h1 id="给-ai-权限之前先看懂-codex-沙箱、审批与安全边界" tabindex="-1">给 AI 权限之前先看懂：Codex 沙箱、审批与安全边界 <a class="header-anchor" href="#给-ai-权限之前先看懂-codex-沙箱、审批与安全边界" aria-label="Permalink to &quot;给 AI 权限之前先看懂：Codex 沙箱、审批与安全边界&quot;">​</a></h1><p>Codex 能读文件、运行命令和调用外部工具，因此安全不能只依赖一句“不要做危险操作”。OpenAI Docs 当前把本地控制拆成 Sandbox 与 Approval：前者决定技术上能接触什么，后者决定何时必须暂停并由人或自动审查器判断。</p><h2 id="一、sandbox-与-approval-不能混用" tabindex="-1">一、Sandbox 与 Approval 不能混用 <a class="header-anchor" href="#一、sandbox-与-approval-不能混用" aria-label="Permalink to &quot;一、Sandbox 与 Approval 不能混用&quot;">​</a></h2><h3 id="_1-1-sandbox-是强制执行边界" tabindex="-1">1.1 Sandbox 是强制执行边界 <a class="header-anchor" href="#_1-1-sandbox-是强制执行边界" aria-label="Permalink to &quot;1.1 Sandbox 是强制执行边界&quot;">​</a></h3><p>它限制命令可以读取或写入的路径、是否能够访问网络，以及能否接触工作区外资源。Git、包管理器、测试程序和脚本子进程同样继承边界。</p><h3 id="_1-2-approval-是例外决策机制" tabindex="-1">1.2 Approval 是例外决策机制 <a class="header-anchor" href="#_1-2-approval-是例外决策机制" aria-label="Permalink to &quot;1.2 Approval 是例外决策机制&quot;">​</a></h3><p>当动作需要越过当前边界时，Codex 可以说明目标、范围和原因，再请求批准。批准一个精确动作，不等于永久放开全部系统。</p><h3 id="_1-3-自动审查只改变审查者" tabindex="-1">1.3 自动审查只改变审查者 <a class="header-anchor" href="#_1-3-自动审查只改变审查者" aria-label="Permalink to &quot;1.3 自动审查只改变审查者&quot;">​</a></h3><p>Approve for me 或 Auto-review 可以处理符合条件的请求，但不会自动扩大 Sandbox。自动审查仍应执行组织策略，无法判断时应升级给人。</p><p><img src="'+i+'" alt="图 1：沙箱技术边界与审批决策边界协同工作"></p><h2 id="二、权限模式围绕任务选择" tabindex="-1">二、权限模式围绕任务选择 <a class="header-anchor" href="#二、权限模式围绕任务选择" aria-label="Permalink to &quot;二、权限模式围绕任务选择&quot;">​</a></h2><h3 id="_2-1-只读适合调查与规划" tabindex="-1">2.1 只读适合调查与规划 <a class="header-anchor" href="#_2-1-只读适合调查与规划" aria-label="Permalink to &quot;2.1 只读适合调查与规划&quot;">​</a></h3><p>架构分析、日志诊断和方案讨论通常不需要修改文件。只读边界能证明本轮不会改变仓库状态。</p><h3 id="_2-2-工作区写入适合常规开发" tabindex="-1">2.2 工作区写入适合常规开发 <a class="header-anchor" href="#_2-2-工作区写入适合常规开发" aria-label="Permalink to &quot;2.2 工作区写入适合常规开发&quot;">​</a></h3><p>代理可以在活动工作区编辑并运行常规本地命令，网络和工作区外动作继续受到限制或审批。这是低摩擦开发的常见边界。</p><h3 id="_2-3-全访问必须明确接受风险" tabindex="-1">2.3 全访问必须明确接受风险 <a class="header-anchor" href="#_2-3-全访问必须明确接受风险" aria-label="Permalink to &quot;2.3 全访问必须明确接受风险&quot;">​</a></h3><p>Full access 或 danger-full-access 移除重要隔离，不应为了少几次提示而默认启用。高权限适用于用户明确接受广泛访问且环境本身已经隔离的场景。</p><h3 id="_2-4-permission-profile-表达最小能力" tabindex="-1">2.4 Permission Profile 表达最小能力 <a class="header-anchor" href="#_2-4-permission-profile-表达最小能力" aria-label="Permalink to &quot;2.4 Permission Profile 表达最小能力&quot;">​</a></h3><p>命名 Profile 可以组合文件与网络规则，让只读审计、项目编辑和特定工具访问形成可复用边界。更窄的拒绝规则应继续保护 <code>.env</code> 等敏感路径。</p><p><img src="'+s+'" alt="图 2：只读、工作区与自定义 Profile 的权限梯度"></p><h2 id="三、网络许可与内容可信是两回事" tabindex="-1">三、网络许可与内容可信是两回事 <a class="header-anchor" href="#三、网络许可与内容可信是两回事" aria-label="Permalink to &quot;三、网络许可与内容可信是两回事&quot;">​</a></h2><h3 id="_3-1-默认关闭网络减少外泄面" tabindex="-1">3.1 默认关闭网络减少外泄面 <a class="header-anchor" href="#_3-1-默认关闭网络减少外泄面" aria-label="Permalink to &quot;3.1 默认关闭网络减少外泄面&quot;">​</a></h3><p>本地工作区写入不应被理解为任意联网。需要下载依赖或访问服务时，按任务启用网络，并尽量限制到必要域名。</p><h3 id="_3-2-web-search-与命令网络可能分离" tabindex="-1">3.2 Web Search 与命令网络可能分离 <a class="header-anchor" href="#_3-2-web-search-与命令网络可能分离" aria-label="Permalink to &quot;3.2 Web Search 与命令网络可能分离&quot;">​</a></h3><p>搜索工具、浏览器、插件和本地命令使用不同控制。允许搜索官方文档，不代表任意脚本可以访问互联网。</p><h3 id="_3-3-白名单不能证明远端内容安全" tabindex="-1">3.3 白名单不能证明远端内容安全 <a class="header-anchor" href="#_3-3-白名单不能证明远端内容安全" aria-label="Permalink to &quot;3.3 白名单不能证明远端内容安全&quot;">​</a></h3><p>依赖脚本、Issue、网页和文档都可能包含恶意或误导内容。域名策略限制目的地，内容审查和工具权限限制后续动作。</p><p><img src="'+c+'" alt="图 3：网络开关、域名策略与内容信任构成三层边界"></p><h2 id="四、prompt-injection-是指令权混淆" tabindex="-1">四、Prompt Injection 是指令权混淆 <a class="header-anchor" href="#四、prompt-injection-是指令权混淆" aria-label="Permalink to &quot;四、Prompt Injection 是指令权混淆&quot;">​</a></h2><p>代理读取网页、仓库说明或日志时，其中的文字只是任务数据，不能自动覆盖系统、用户与项目规则。可靠防护不只识别“忽略前文”之类句式，而是同时限制秘密读取、网络出口、工具副作用和最终发布动作。</p><p><img src="'+n+'" alt="图 4：不可信输入经过指令层级与工具边界拦截"></p><h2 id="五、secrets-必须离开普通上下文" tabindex="-1">五、Secrets 必须离开普通上下文 <a class="header-anchor" href="#五、secrets-必须离开普通上下文" aria-label="Permalink to &quot;五、Secrets 必须离开普通上下文&quot;">​</a></h2><h3 id="_5-1-不把密钥写进-prompt" tabindex="-1">5.1 不把密钥写进 Prompt <a class="header-anchor" href="#_5-1-不把密钥写进-prompt" aria-label="Permalink to &quot;5.1 不把密钥写进 Prompt&quot;">​</a></h3><p>Prompt、源码、提交和普通日志都不是秘密存储。需要认证时使用官方登录、受控环境变量或组织秘密管理系统。</p><h3 id="_5-2-缩短凭据生命周期" tabindex="-1">5.2 缩短凭据生命周期 <a class="header-anchor" href="#_5-2-缩短凭据生命周期" aria-label="Permalink to &quot;5.2 缩短凭据生命周期&quot;">​</a></h3><p>能使用短期令牌就不共享长期 Token。云端环境可以把 Secrets 限制在设置阶段，避免在代理执行阶段持续暴露。</p><h3 id="_5-3-输出同样要防止泄漏" tabindex="-1">5.3 输出同样要防止泄漏 <a class="header-anchor" href="#_5-3-输出同样要防止泄漏" aria-label="Permalink to &quot;5.3 输出同样要防止泄漏&quot;">​</a></h3><p>命令回显、错误日志、Diff 和聊天回复都可能带出敏感值。验证流程应包含秘密扫描和输出边界检查。</p><p><img src="'+l+'" alt="图 5：秘密从存储到短期使用再到输出检查"></p><h2 id="六、高风险动作保留人工责任" tabindex="-1">六、高风险动作保留人工责任 <a class="header-anchor" href="#六、高风险动作保留人工责任" aria-label="Permalink to &quot;六、高风险动作保留人工责任&quot;">​</a></h2><p>删除文件、覆盖 Git 历史、数据库迁移、密钥轮换、发送外部消息、合并、部署和公开发布，具有不可逆或多人影响。代理可以准备目标清单、影响分析、Dry-run、恢复方式和验证证据，最终确认仍由责任人完成。</p><p>审批时应核对动作意图、精确目标、必要原因、可逆性和授权范围。能批准一个命令，就不批准整个会话；能开放一个域名，就不开放任意网络。</p><p><img src="'+p+'" alt="图 6：动作意图经过影响评估与最小授权进入人工责任点"></p><h2 id="七、官方参考资料" tabindex="-1">七、官方参考资料 <a class="header-anchor" href="#七、官方参考资料" aria-label="Permalink to &quot;七、官方参考资料&quot;">​</a></h2><p><a href="https://learn.chatgpt.com/docs/agent-approvals-security" target="_blank" rel="noreferrer">OpenAI Docs：Agent approvals &amp; security</a></p><p><a href="https://learn.chatgpt.com/docs/permissions" target="_blank" rel="noreferrer">OpenAI Docs：Permissions</a></p><p><a href="https://learn.chatgpt.com/docs/sandboxing" target="_blank" rel="noreferrer">OpenAI Docs：Sandbox</a></p><p><a href="https://learn.chatgpt.com/docs/security" target="_blank" rel="noreferrer">OpenAI Docs：Security</a></p>',49)])])}const g=e(d,[["render",h]]);export{q as __pageData,g as default};
